                        let count = state
                            .clicking
                            .get(&hovered_entity)
                            .map_or(1, |(_, count)| *count);
                        state.clicking.insert(hovered_entity, (now, count));
                        let click_event = PointerClick {
                            pointer: pointer.clone(),
                            entity: hovered_entity,
                            button,
                            hit: hit.clone(),
                            duration: now - *press_instant,
