                                entity: hovered_entity,
                                button,
                                dragged: *drag_target,
                                hit: hit.clone(),
                            };
                            commands.trigger(drag_over_event.clone());
                            message_writers.drag_over_events.write(drag_over_event);
                        }
                    }
                }

